setup:
cat > tests/invoice.test.js <<'BENCHEOF'
import { test } from "node:test";
import assert from "node:assert";
import { render } from "../src/billing/invoice.ts";

test("an invoice renders its line items and its total", () => {
  const text = render({
    orderId: "ord_1",
    total: 1200,
    lines: [{ label: "Widget", amount: 1000 }],
  });
  assert.equal(text, "Invoice for ord_1\nWidget: \u00a310.00\nTotal: \u00a312.00");
});
BENCHEOF
